"""Build a self-contained documentation website; pip install -r build/requirements-docs.txt."""
from pathlib import Path
import json,re,html
import markdown
R=Path(__file__).resolve().parent.parent;out=R/'docs/site';out.mkdir(parents=True,exist_ok=True)
pages=[('index.html','Подключение','INSTALL.md'),('api.html','API guide','API.md'),('reference.html','Методы','REFERENCE.md'),('recipes.html','Примеры','RECIPES.md'),('composition.html','Тема и составные строки','COMPOSITE.md')]
css='''*{box-sizing:border-box} :root{color-scheme:light dark;--bg:#fff;--surface:#f9f8f7;--raised:#f0efed;--text:#2c2c2b;--muted:#66635e;--border:#e6e5e3;--blue:#1767b4} @media(prefers-color-scheme:dark){:root{--bg:#191919;--surface:#202020;--raised:#383836;--text:#fff;--muted:#b5b5b3;--border:#484847;--blue:#83baf5}}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--blue);text-underline-offset:3px}header{height:72px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 32px;position:sticky;top:0;background:var(--bg);z-index:10;gap:24px}.brand{font-size:18px;font-weight:650;color:var(--text);text-decoration:none;white-space:nowrap}.brand span{color:var(--muted);font-size:14px;font-weight:400;margin-left:8px}header a.repo{font-size:14px}.shell{max-width:1200px;margin:auto;display:grid;grid-template-columns:248px minmax(0,1fr);gap:48px;padding:32px}aside{position:sticky;top:104px;align-self:start;max-height:calc(100vh - 125px);overflow:auto;padding:0 16px 24px 0}nav a{display:block;color:var(--muted);text-decoration:none;min-height:44px;padding:10px 12px;border-radius:8px;font-size:14px}nav a:hover,nav a[aria-current=page]{color:var(--text);background:var(--raised)}.eyebrow{color:var(--muted);font-size:12px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;margin:24px 12px 8px}.toc ul{list-style:none;padding-left:0;margin:0}.toc ul ul{display:block;padding-left:8px}.toc ul ul ul{display:none}.toc a{font-size:14px;padding:6px 12px;min-height:36px}.search{margin-bottom:16px}input{width:100%;height:44px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);padding:0 12px;font:inherit;font-size:14px}main{min-width:0;overflow-x:hidden;max-width:800px;padding-bottom:80px}h1{font-size:40px;line-height:1.15;letter-spacing:-.035em;margin:8px 0 24px;font-weight:650}h2{font-size:25px;line-height:1.3;margin:48px 0 16px;letter-spacing:-.02em}h3{font-size:20px;margin:32px 0 12px}p{margin:0 0 16px}li{margin:8px 0}code{font:14px/1.6 Consolas,"Liberation Mono",monospace;background:var(--raised);padding:2px 5px;border-radius:4px;overflow-wrap:anywhere}pre{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:48px 20px 20px;overflow:auto;position:relative;margin:24px 0}pre code{background:none;padding:0;white-space:pre;overflow-wrap:normal}pre button{position:absolute;right:8px;top:4px;min-height:36px;min-width:90px;border:0;border-radius:6px;background:var(--raised);color:var(--text);cursor:pointer;font:14px system-ui}.table-wrap{overflow:auto;margin:24px 0;border:1px solid var(--border);border-radius:8px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--border);padding:12px 16px;vertical-align:top}th{background:var(--surface);font-weight:600}tr:last-child td{border-bottom:0}blockquote{border-left:3px solid var(--blue);margin:24px 0;padding:8px 20px;background:var(--surface)}footer{border-top:1px solid var(--border);margin-top:48px;padding-top:24px;color:var(--muted);font-size:14px}.mobile-nav{display:none}.results{margin:16px 0}.results a{display:block;padding:12px;background:var(--surface);margin:8px 0;border:1px solid var(--border);border-radius:8px;text-decoration:none}.results small{display:block;color:var(--muted);font-size:14px}img{max-width:100%}:focus-visible{outline:3px solid var(--blue);outline-offset:3px}h1,h2,h3{scroll-margin-top:100px}@media(max-width:760px){header{height:64px;padding:0 20px}.brand span{display:none}.shell{display:block;padding:24px 20px}.desktop-nav{display:none}aside{position:static;max-height:none;padding:0;margin:0 0 32px}.mobile-nav{display:block;border:1px solid var(--border);border-radius:8px;padding:10px 12px}.mobile-nav summary{min-height:30px;cursor:pointer;font-size:14px}h1{font-size:32px}h2{font-size:24px}header a.repo{font-size:14px}pre{padding-left:16px;padding-right:16px}.toc{display:none}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'''
(out/'style.css').write_text(css)
corpus=[];rendered=[]
for route,title,source in pages:
 text=(R/'docs/remake-2'/source).read_text()
 md=markdown.Markdown(extensions=['fenced_code','tables','toc','sane_lists']);body=md.convert(text)
 # Route internal documentation links locally. Source/examples continue to GitHub.
 for rt,_,src in pages:body=body.replace('href="'+src+'"','href="'+rt+'"')
 body=re.sub(r'href="\.\./\.\./([^"#]+)(#[^"]*)?"',lambda m:'href="https://github.com/123ads213/WindUI-Remake-2/blob/main/'+m[1]+(m[2]or'')+'"',body)
 body=re.sub(r'<table>(.*?)</table>',r'<div class="table-wrap"><table>\1</table></div>',body,flags=re.S)
 nav=''.join('<a href="'+rt+'"'+(' aria-current="page"'if rt==route else'')+'>'+label+'</a>'for rt,label,_ in pages)
 toc=md.toc
 page=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · WindUI Remake 2</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">WindUI <span>Remake 2 / Documentation</span></a><a class="repo" href="https://github.com/123ads213/WindUI-Remake-2">GitHub ↗</a></header><div class="shell"><aside><div class="search"><input id="search" type="search" aria-label="Поиск по документации" placeholder="Поиск методов…"></div><nav class="desktop-nav" aria-label="Документация">{nav}</nav><details class="mobile-nav"><summary>Разделы документации</summary><nav>{nav}</nav></details><div class="desktop-nav eyebrow">На этой странице</div><nav class="toc" aria-label="Содержание">{toc}</nav></aside><main><div id="results" class="results" aria-live="polite"></div><article>{body}</article><footer>WindUI Remake 2 · Original WindUI by Footagesus · MIT<br>Сайт собран из Markdown и исходников в этом репозитории. <a href="https://github.com/123ads213/WindUI-Remake-2/blob/main/docs/remake-2/{source}">Редактировать источник ↗</a></footer></main></div><script src="search-index.js"></script><script src="site.js"></script></body></html>'''
 (out/route).write_text(page)
 for m in re.finditer(r'<h[123][^>]*id="([^"]+)"[^>]*>(.*?)</h[123]>(.*?)(?=<h[123]|$)',body,flags=re.S):
  clean=lambda x:html.unescape(re.sub('<[^>]*>',' ',x))
  corpus.append({'title':clean(m[2]),'text':re.sub(r'\s+',' ',clean(m[3])),'url':route+'#'+m[1]})
(out/'search-index.js').write_text('window.DOCS_INDEX='+json.dumps(corpus,ensure_ascii=False)+';')
(out/'site.js').write_text('''document.querySelectorAll('pre').forEach(pre=>{const b=document.createElement('button');b.textContent='Копировать';b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(pre.querySelector('code').textContent);b.textContent='Скопировано';setTimeout(()=>b.textContent='Копировать',1500)}catch{b.textContent='Выделите код'}});pre.append(b)});const input=document.getElementById('search'),results=document.getElementById('results');input.addEventListener('input',()=>{const q=input.value.toLocaleLowerCase().trim();results.replaceChildren();document.querySelector('article').hidden=!!q;if(!q)return;const found=window.DOCS_INDEX.filter(x=>(x.title+' '+x.text).toLocaleLowerCase().includes(q)).slice(0,20);if(!found.length){results.textContent='Ничего не найдено. Попробуйте имя метода, например SetSort.';return}found.forEach(x=>{const a=document.createElement('a');a.href=x.url;a.textContent=x.title;const small=document.createElement('small');small.textContent=x.text.slice(0,150)+'…';a.append(small);results.append(a)})});document.addEventListener('click',e=>{if(e.target.closest('#results a')){input.value='';results.replaceChildren();document.querySelector('article').hidden=false}});''')
(out/'.nojekyll').write_text('')
print('Built documentation:',len(pages),'pages;',len(corpus),'searchable sections')
